Researchers, students, public health professionals, and decision-makers from across the region working on infectious disease modelling.
Apply to join MIDSEA!

function splitName(name) {
  const m = (name || "").trim().match(/^([^\s,"]+)([\s\S]*)$/);
  return m ? {first: m[1], rest: m[2]} : {first: (name || "").trim(), rest: ""};
}

function firstName(name) {
  return splitName(name).first;
}

// Wrap the first word of a display name so styles.scss can bold it
function boldFirstName(name) {
  const {first, rest} = splitName(name);
  return html`&lt;span class="person-first-name"&gt;${first}&lt;/span&gt;${rest}`;
}

function byName(a, b) {
  const opts = {sensitivity: "base"};
  return firstName(a.name).localeCompare(firstName(b.name), undefined, opts)
    || (a.name || "").localeCompare(b.name || "", undefined, opts);
}

people = FileAttachment("people.csv").csv({typed: false})
  .then(rows =&gt; rows.sort(byName))

// The site can be served under a subpath (GitHub Pages project page:
// &lt;org&gt;.github.io/midsea-network/), so a "/images/..." path must resolve
// against the site root, not the domain root. This page is one folder deep.
siteRoot = new URL("../", location.href).href

function siteUrl(path) {
  // Full URLs (https://...) pass through new URL() unchanged.
  return new URL(path.replace(/^\/(?!\/)/, ""), siteRoot).href;
}

placeholderAvatar = siteUrl("images/people/placeholder-avatar.svg")

// people.csv stores the SHA-256 of the lower-cased email, never the email
// itself: the CSV is published with the site. Gravatar looks up by that hash.
function gravatarUrl(hash) {
  // d=404 makes Gravatar return 404 when the email has no Gravatar, so the
  // &lt;img&gt; onerror swaps in our placeholder. Gravatar cannot use our SVG as
  // its d= default: it only accepts public .jpg/.gif/.png URLs.
  return `https://www.gravatar.com/avatar/${hash}?s=200&d=404`;
}

function photoUrl(p) {
  if (p.photo && p.photo.trim()) return siteUrl(p.photo.trim());
  if (p.email_sha256 && p.email_sha256.trim()) return gravatarUrl(p.email_sha256.trim());
  return placeholderAvatar;
}

photoUrls = people.map(photoUrl)

// The Cards / Compact switch only toggles a class on the grid; the compact
// layout (small round photo beside the name) lives in styles.scss.
{
  const grid = html`&lt;div class="people-grid"&gt;
    ${people.map((p, i) =&gt; html`
      &lt;div class="person-card"&gt;
        &lt;img src="${photoUrls[i]}" alt="${p.name}"
          onerror="this.onerror=null;this.src='${placeholderAvatar}';"&gt;
        &lt;div class="person-card-body"&gt;
          &lt;h3&gt;${p.profile_url && p.profile_url.trim()
            ? html`&lt;a href="${p.profile_url}" target="_blank" rel="noopener noreferrer"&gt;${boldFirstName(p.name)}&lt;i class="bi bi-box-arrow-up-right person-link-icon" aria-hidden="true"&gt;&lt;/i&gt;&lt;span class="visually-hidden"&gt; (opens in a new tab)&lt;/span&gt;&lt;/a&gt;`
            : boldFirstName(p.name)}&lt;/h3&gt;
          &lt;p class="person-title"&gt;${p.title}&lt;/p&gt;
          &lt;p class="person-institution"&gt;${p.institution}&lt;/p&gt;
        &lt;/div&gt;
      &lt;/div&gt;
    `)}
  &lt;/div&gt;`;

  const toolbar = html`&lt;div class="people-toolbar"&gt;
    &lt;div class="btn-group btn-group-sm" role="group" aria-label="People view"&gt;
      &lt;input type="radio" class="btn-check" name="people-view"
        id="people-view-cards" value="cards" checked&gt;
      &lt;label class="btn btn-outline-primary" for="people-view-cards"&gt;
        &lt;i class="bi bi-grid-3x3-gap" aria-hidden="true"&gt;&lt;/i&gt; Cards
      &lt;/label&gt;
      &lt;input type="radio" class="btn-check" name="people-view"
        id="people-view-compact" value="compact"&gt;
      &lt;label class="btn btn-outline-primary" for="people-view-compact"&gt;
        &lt;i class="bi bi-list-ul" aria-hidden="true"&gt;&lt;/i&gt; Compact
      &lt;/label&gt;
    &lt;/div&gt;
  &lt;/div&gt;`;

  toolbar.addEventListener("change", e =&gt; {
    grid.classList.toggle("people-grid-compact", e.target.value === "compact");
  });

  return html`&lt;div class="people-directory"&gt;${toolbar}${grid}&lt;/div&gt;`;
}
